#include <iostream>
#include <algorithm>
#include <vector>
#include <set>

#define ll long long
#define ft first
#define sd second

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

#ifdef FREOPEN
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    ll n, k;
    cin >> n >> k;

    vector<ll> c(n), ans(k + 1), sum(k + 1);

    for (ll i = 0; i < n; ++i) {
        cin >> c[i];
    }

    sort(c.begin(), c.end());
    reverse(c.begin(), c.end());

    set<pair<ll, ll>> s;
    for (ll i = 0; i <= k; ++i) {
        s.insert({0, i});
    }

    for (const auto &value : c) {
        ll ind = s.begin()->sd;
        s.erase(s.begin());
        ans[ind] += sum[ind];
        sum[ind] += value;
        s.insert({-sum[ind], ind});
    }

    ll out = 0;
    for (ll i = 0; i <= k; ++i) {
        out += ans[i];
    }

    cout << out;
    return 0;
}

